import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64
// Optimization: improve shared-memory reuse and load-instruction density.
// The 4x121 per-channel weights are now cooperatively staged into shared
// memory with a padded row stride of 12, and the staged input tile uses a
// padded 72-element row stride, so every aligned adjacent tap pair in the
// inner loop is fetched with one ld.shared.v2.f32 instead of two scalar
// loads. This halves load instructions per FMA in the accumulation loop,
// turns all weight reads into shared-memory broadcasts (removing repeated
// global/L1 weight traffic from the hot loop), and keeps the 16x16
// spatial tile, 4-way output-channel register blocking, halo staging,
// accumulation order per output channel, occupancy target (smem stays
// ~22KB/CTA => 4 CTAs/SM), and sm_89 scalar FP32 FMA semantics unchanged.
.visible .entry conv2d_3x96_k11_s4_p2(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elems
)
{
    .reg .pred %p, %q;
    .reg .u32 %r_tid, %r_cta, %r_tw, %r_th, %r_ocp, %r_n;
    .reg .u32 %r_tmp, %r_tmp2, %r_idx, %r_row, %r_col, %r_addr;
    .reg .u32 %r_sy, %r_sx, %r_oy, %r_ox, %r_oc0, %r_inb, %r_wbase;
    .reg .u32 %r_ic, %r_ky, %r_kx, %r_sin, %r_sbase, %r_saddr;
    .reg .u32 %r_sinw, %r_waddr, %r_ocw, %r_rem;
    .reg .s32 %s_h0, %s_w0, %s_ih, %s_iw;
    .reg .u64 %rd_in, %rd_wt, %rd_bias, %rd_out, %rd_addr, %rd_off, %rd_waddr;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3, %f_a, %f_a0, %f_a1;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_b3, %f_b4, %f_b5, %f_b6, %f_b7;
    .shared .align 16 .f32 smem_in[5112];
    .shared .align 16 .f32 smem_wt[528];
    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_wt, [wt_ptr];
    ld.param.u64 %rd_bias, [bias_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_cta, %ctaid.x;
    // decompose ctaid.x: tw in [0,4), th in [0,4), ocp in [0,24), n
    rem.u32 %r_tw, %r_cta, 4;
    div.u32 %r_tmp, %r_cta, 4;
    rem.u32 %r_th, %r_tmp, 4;
    div.u32 %r_tmp, %r_tmp, 4;
    rem.u32 %r_ocp, %r_tmp, 24;
    div.u32 %r_n, %r_tmp, 24;
    mov.u32 %r_sin, smem_in;
    mov.u32 %r_sinw, smem_wt;
    // input halo origin: h0 = th*64 - 2, w0 = tw*64 - 2
    shl.b32 %r_tmp, %r_th, 6;
    cvt.s32.u32 %s_h0, %r_tmp;
    sub.s32 %s_h0, %s_h0, 2;
    shl.b32 %r_tmp, %r_tw, 6;
    cvt.s32.u32 %s_w0, %r_tmp;
    sub.s32 %s_w0, %s_w0, 2;
    // thread spatial coords inside 16x16 tile
    shr.u32 %r_sy, %r_tid, 4;
    and.b32 %r_sx, %r_tid, 15;
    shl.b32 %r_oy, %r_th, 4;
    add.u32 %r_oy, %r_oy, %r_sy;
    shl.b32 %r_ox, %r_tw, 4;
    add.u32 %r_ox, %r_ox, %r_sx;
    // shared input base element index for this thread: sy*284 + sx*4
    mul.lo.u32 %r_inb, %r_sy, 288;
    shl.b32 %r_tmp, %r_sx, 2;
    add.u32 %r_inb, %r_inb, %r_tmp;
    // shared byte address base for this thread (invariant across ic/ky/kx)
    shl.b32 %r_sbase, %r_inb, 2;
    add.u32 %r_sbase, %r_sbase, %r_sin;
    // global element base for this CTA's four adjacent output channels
    mul.lo.u32 %r_wbase, %r_ocp, 1452;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    mov.u32 %r_ic, 0;
L_ic:
    setp.ge.u32 %p, %r_ic, 3;
    @%p bra L_ic_done;
    // global element offset of channel start: (n*3 + ic)*50176
    mul.lo.u32 %r_tmp, %r_n, 3;
    add.u32 %r_tmp, %r_tmp, %r_ic;
    mul.lo.u32 %r_tmp, %r_tmp, 50176;
    // cooperative staging of 71x71 halo tile for this channel (zero pad)
    mov.u32 %r_idx, %r_tid;
L_stage:
    setp.ge.u32 %p, %r_idx, 5041;
    @%p bra L_stage_done;
    div.u32 %r_row, %r_idx, 71;
    rem.u32 %r_col, %r_idx, 71;
    mul.lo.u32 %r_addr, %r_row, 72;
    add.u32 %r_addr, %r_addr, %r_col;
    shl.b32 %r_addr, %r_addr, 2;
    add.u32 %r_addr, %r_addr, %r_sin;
    cvt.s32.u32 %s_ih, %r_row;
    add.s32 %s_ih, %s_ih, %s_h0;
    cvt.s32.u32 %s_iw, %r_col;
    add.s32 %s_iw, %s_iw, %s_w0;
    mov.f32 %f_a, 0f00000000;
    setp.lt.s32 %p, %s_ih, 0;
    setp.ge.s32 %q, %s_ih, 224;
    or.pred %p, %p, %q;
    setp.lt.s32 %q, %s_iw, 0;
    or.pred %p, %p, %q;
    setp.ge.s32 %q, %s_iw, 224;
    or.pred %p, %p, %q;
    @%p bra L_stage_store;
    cvt.u32.s32 %r_tmp2, %s_ih;
    mul.lo.u32 %r_tmp2, %r_tmp2, 224;
    add.u32 %r_tmp2, %r_tmp2, %r_tmp;
    cvt.u32.s32 %r_row, %s_iw;
    add.u32 %r_tmp2, %r_tmp2, %r_row;
    cvt.u64.u32 %rd_off, %r_tmp2;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_a, [%rd_addr];
L_stage_store:
    st.shared.f32 [%r_addr], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_stage;
L_stage_done:
    // cooperative staging of the 4x121 weights for this channel into padded
    // shared memory (row stride 12 keeps every kx pair 8-byte aligned)
    mov.u32 %r_idx, %r_tid;
L_wstage:
    setp.ge.u32 %p, %r_idx, 484;
    @%p bra L_wstage_done;
    div.u32 %r_ocw, %r_idx, 121;
    rem.u32 %r_rem, %r_idx, 121;
    div.u32 %r_row, %r_rem, 11;
    rem.u32 %r_col, %r_rem, 11;
    // Global OIHW element offset: wbase + ocw*(3*11*11) + ic*(11*11) + ky*11 + kx
    mul.lo.u32 %r_tmp2, %r_ocw, 363;
    add.u32 %r_tmp2, %r_tmp2, %r_wbase;
    mul.lo.u32 %r_addr, %r_ic, 121;
    add.u32 %r_tmp2, %r_tmp2, %r_addr;
    add.u32 %r_tmp2, %r_tmp2, %r_rem;
    cvt.u64.u32 %rd_off, %r_tmp2;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_wt, %rd_off;
    ld.global.f32 %f_a, [%rd_addr];
    mul.lo.u32 %r_tmp2, %r_ocw, 132;
    mul.lo.u32 %r_addr, %r_row, 12;
    add.u32 %r_tmp2, %r_tmp2, %r_addr;
    add.u32 %r_tmp2, %r_tmp2, %r_col;
    shl.b32 %r_tmp2, %r_tmp2, 2;
    add.u32 %r_tmp2, %r_tmp2, %r_sinw;
    st.shared.f32 [%r_tmp2], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_wstage;
L_wstage_done:
    bar.sync 0;
    // per-channel base addresses for the accumulation loops
    mov.u32 %r_saddr, %r_sbase;
    mov.u32 %r_waddr, %r_sinw;
    // accumulate 11x11 from shared tile into four output accumulators.
    // register-blocked over kx: two taps per iteration, incremental
    // byte-address updates, odd tap (kx=10) handled as an explicit tail.
    mov.u32 %r_ky, 0;
L_ky:
    setp.ge.u32 %p, %r_ky, 11;
    @%p bra L_ky_done;
    mov.u32 %r_kx, 0;
L_kx:
    // taps (ky,kx) and (ky,kx+1), each reused for four output channels
    ld.shared.v2.f32 {%f_a0, %f_a1}, [%r_saddr];
    ld.shared.v2.f32 {%f_b0, %f_b4}, [%r_waddr];
    ld.shared.v2.f32 {%f_b1, %f_b5}, [%r_waddr+528];
    ld.shared.v2.f32 {%f_b2, %f_b6}, [%r_waddr+1056];
    ld.shared.v2.f32 {%f_b3, %f_b7}, [%r_waddr+1584];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc2, %f_a0, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_a0, %f_b3, %f_acc3;
    fma.rn.f32 %f_acc0, %f_a1, %f_b4, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a1, %f_b5, %f_acc1;
    fma.rn.f32 %f_acc2, %f_a1, %f_b6, %f_acc2;
    fma.rn.f32 %f_acc3, %f_a1, %f_b7, %f_acc3;
    add.u32 %r_saddr, %r_saddr, 8;
    add.u32 %r_waddr, %r_waddr, 8;
    add.u32 %r_kx, %r_kx, 2;
    setp.lt.u32 %p, %r_kx, 10;
    @%p bra L_kx;
    // tail tap (ky,10)
    ld.shared.f32 %f_a0, [%r_saddr];
    ld.shared.f32 %f_b0, [%r_waddr];
    ld.shared.f32 %f_b1, [%r_waddr+528];
    ld.shared.f32 %f_b2, [%r_waddr+1056];
    ld.shared.f32 %f_b3, [%r_waddr+1584];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc2, %f_a0, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_a0, %f_b3, %f_acc3;
    // advance addresses to tap (ky+1,0): +62 input elems / +2 weight elems
    add.u32 %r_saddr, %r_saddr, 248;
    add.u32 %r_waddr, %r_waddr, 8;
    add.u32 %r_ky, %r_ky, 1;
    bra L_ky;
L_ky_done:
    bar.sync 0;
    add.u32 %r_ic, %r_ic, 1;
    bra L_ic;
L_ic_done:
    // epilogue: add bias and store four output channels
    shl.b32 %r_oc0, %r_ocp, 2;
    cvt.u64.u32 %rd_off, %r_oc0;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_bias, %rd_off;
    ld.global.f32 %f_b0, [%rd_addr];
    ld.global.f32 %f_b1, [%rd_addr + 4];
    ld.global.f32 %f_b2, [%rd_addr + 8];
    ld.global.f32 %f_b3, [%rd_addr + 12];
    add.f32 %f_acc0, %f_acc0, %f_b0;
    add.f32 %f_acc1, %f_acc1, %f_b1;
    add.f32 %f_acc2, %f_acc2, %f_b2;
    add.f32 %f_acc3, %f_acc3, %f_b3;
    setp.ge.u32 %p, %r_oy, 55;
    setp.ge.u32 %q, %r_ox, 55;
    or.pred %p, %p, %q;
    @%p bra L_done;
    mul.lo.u32 %r_tmp, %r_n, 96;
    add.u32 %r_tmp, %r_tmp, %r_oc0;
    mul.lo.u32 %r_tmp, %r_tmp, 55;
    add.u32 %r_tmp, %r_tmp, %r_oy;
    mul.lo.u32 %r_tmp, %r_tmp, 55;
    add.u32 %r_tmp, %r_tmp, %r_ox;
    cvt.u64.u32 %rd_off, %r_tmp;
    shl.b64 %rd_off, %rd_off, 2;
    add.u64 %rd_addr, %rd_out, %rd_off;
    st.global.f32 [%rd_addr], %f_acc0;
    st.global.f32 [%rd_addr + 12100], %f_acc1;
    st.global.f32 [%rd_addr + 24200], %f_acc2;
    st.global.f32 [%rd_addr + 36300], %f_acc3;
L_done:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
